class Solution:
    def minMovesToCaptureTheQueen(self, a: int, b: int, c: int, d: int, e: int, f: int) -> int:
        # Check if the rook can capture the queen in one move
        if a == e and not (a == c and min(b, f) <= d <= max(b, f)):
            return 1

        # Check if the bishop can capture the queen in one move
        if b == f and not (b == d and min(a, e) <= c <= max(a, e)):
            return 1

        # Check if both pieces can capture the queen in two moves
        if abs(c - e) == abs(d - f):
            return 2

        # Check if the rook can move to a position to capture the queen in two moves
        if (abs(a - e) == abs(b - f)) and (min(c, e) <= a <= max(c, e)) and (min(d, f) <= b <= max(d, f)):
            return 2

        # If none of the above conditions are met, the bishop can capture the queen in one move
        return 1

